def entropy(p):
    import math
    if p in (0,1): return 0
    return -(p*math.log2(p)+(1-p)*math.log2(1-p))
def build(X,Y,depth=0,maxd=8):
    p=Y.mean()
    if depth==maxd or len(set(Y))==1: return ('L',p,len(Y))
    bf,bt,bs=None,None,1e9
    n=len(Y)
    for f in range(X.shape[1]):
        v=X[:,f]
        for th in (0.5,):
            m=v<=th
            if m.all() or (~m).all(): continue
            e=(m.sum()/n)*entropy(Y[m].mean())+((~m).sum()/n)*entropy(Y[~m].mean())
            if e<bs: bs,bf,bt=e,f,th
    m=X[:,bf]<=bt
