        d1.setdefault(y-x,set()).add(y); d2.setdefault(y+x,set()).add(y)
    def f(y,x):
        n=0
        for line,val,coord in ((rows.get(y),y,x),(cols.get(x),x,y),(d1.get(y-x),y-x,y),(d2.get(y+x),y+x,y)):
