def build_tree(rows,depth=0,maxd=8):
    n1=sum(r[1] for r in rows); n0=len(rows)-n1
    if not n0: return ('Y',)
    if not n1: return ('N',)
    if depth>=maxd: return ('L', n1/len(rows))
    best=None
    for fi in range(12):
        vals=sorted(set(r[0][fi] for r in rows))
        for tv in vals[1:]:
            l=[r for r in rows if r[0][fi]<tv]; rr=[r for r in rows if r[0][fi]>=tv]
            if not l or not rr: continue
            def ent(rs):
                a=sum(r[1] for r in rs); b=len(rs)-a
                e=0
                for p in (a/len(rs),b/len(rs)):
                    if p: e-=p*np.log2(p)
                return e
            sc=(ent(l)*len(l)+ent(rr)*len(rr))/len(rows)
            if best is None or sc<best[0]: best=(sc,fi,tv,l,rr)
    _,fi,tv,l,rr=best
    return ('S',fi,tv,build_tree(l,depth+1,maxd),build_tree(rr,depth+1,maxd))
